"""Self-contained, inert-text browser UI for the T052 local reviewer."""

REVIEWER_HTML = r"""<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>ABREX literature review</title>
<style>
:root{--ink:#17202a;--muted:#596776;--line:#d9e0e6;--paper:#fff;--bg:#f3f5f7;--nav:#173f4f;--blue:#176b87;--sf:#ffe08a;--lf:#bde9dc;--danger:#a12b2b}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:15px/1.5 system-ui,sans-serif}header{background:var(--nav);color:#fff;padding:16px 24px}header h1{font-size:20px;margin:0 0 4px}.app{display:grid;grid-template-columns:250px minmax(0,1fr) 330px;gap:16px;max-width:1500px;margin:auto;padding:16px}.panel{background:var(--paper);border:1px solid var(--line);border-radius:10px;padding:16px;box-shadow:0 2px 9px #17202a0d}.sidebar{max-height:calc(100vh - 105px);overflow:auto;position:sticky;top:12px}.case{display:block;width:100%;border:0;border-left:4px solid transparent;background:#fff;color:var(--ink);padding:10px;text-align:left;cursor:pointer}.case:hover,.case:focus{background:#eef5f7}.case.active{background:#dceef3;border-left-color:var(--blue)}.case.reviewed::after{content:' ✓';color:#187044}.filters{display:flex;gap:6px;flex-wrap:wrap;margin:10px 0}.filters button.active{outline:3px solid #8bc4d4}button,.button{border:0;border-radius:6px;background:var(--blue);color:#fff;padding:9px 12px;font-weight:650;cursor:pointer;text-decoration:none}button.secondary,.button.secondary{background:#687783}button.ghost{background:#eaf0f3;color:#24333d}button:disabled{opacity:.55;cursor:wait}.toprow,.actions,.choice-row{display:flex;gap:8px;align-items:center;flex-wrap:wrap}.article-title{font-size:24px;margin:18px 0 4px}.source-line{color:var(--muted);margin-bottom:18px}.source-line a{color:var(--blue)}.instruction{font-size:18px;font-weight:650;margin:8px 0 14px}.passage-box{border:2px solid #91a8b3;border-radius:8px;background:#fff;padding:18px;margin:8px 0}.passage-box h3{margin:0 0 10px;font-size:14px;text-transform:uppercase;letter-spacing:.05em;color:#4a5963}.passage{white-space:pre-wrap;font:18px/1.85 Georgia,serif}.sf{background:var(--sf);border-bottom:3px solid #bc8500}.lf{background:var(--lf);border-bottom:3px solid #14725a}.both{background:linear-gradient(135deg,var(--sf) 50%,var(--lf) 50%)}.legend{display:flex;gap:14px;margin:8px 0;color:var(--muted)}.swatch{display:inline-block;width:18px;height:13px;margin-right:5px;vertical-align:-2px}.context{white-space:pre-wrap;background:#f4f6f7;padding:12px;border-radius:6px;margin-top:8px}.proposal{border:1px solid var(--line);border-radius:8px;padding:12px;margin:10px 0}.proposal h4{margin:0 0 6px}.choice-row label{border:1px solid var(--line);border-radius:6px;padding:6px 8px;cursor:pointer}.editor{border-top:1px solid var(--line);margin-top:12px;padding-top:12px}.field{display:block;margin:10px 0}.field input,.field textarea{display:block;width:100%;border:1px solid #aebbc3;border-radius:6px;padding:8px;font:inherit}.selection{padding:8px;background:#f4f6f7;border-radius:6px;min-height:38px}.banner{padding:9px;border-radius:6px;margin:8px 0}.banner.ok{background:#e4f4e9;color:#155b2c}.banner.error{background:#fde8e8;color:var(--danger)}details{margin:12px 0}summary{cursor:pointer;font-weight:650}.details-content{white-space:pre-wrap;font:13px/1.45 ui-monospace,monospace;background:#f5f6f7;padding:10px;overflow:auto}.missed{border:1px solid var(--line);border-radius:8px;padding:10px;margin:14px 0}.file-label{display:inline-block}.muted{color:var(--muted)}.hidden{display:none!important}@media(max-width:1000px){.app{grid-template-columns:1fr}.sidebar{position:static;max-height:none}.case-list{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr))}}@media(max-width:520px){header{padding:12px}.app{padding:8px;gap:8px}.panel{padding:12px}.article-title{font-size:20px}.passage{font-size:17px}.actions button,.actions .button{width:100%}}
</style><style>
/* Keep span editing out of the primary reading flow until requested. */
.editor:not(.open)>p,.editor:not(.open)>.selection,.editor:not(.open)>.field,.editor:not(.open)>.choice-row:first-of-type{display:none}
</style></head><body>
<header><h1>ABREX literature review</h1><div id="meta">Loading review packet…</div></header>
<div class="app">
<aside class="panel sidebar"><strong>Review cases</strong><div id="counts" class="muted"></div><div id="filters" class="filters"></div><div id="case-list" class="case-list"></div></aside>
<main class="panel"><div class="toprow"><button id="previous" class="ghost">Previous</button><button id="next" class="ghost">Next</button><span id="position" class="muted"></span></div><h2 id="article-title" class="article-title"></h2><div id="source-line" class="source-line"></div><p class="instruction">Check each proposed abbreviation pair. Then say whether this passage contains any missed definition.</p><div class="passage-box"><h3>Passage to review</h3><div class="legend"><span><i class="swatch sf"></i>Short form</span><span><i class="swatch lf"></i>Long form</span></div><div id="passage" class="passage" tabindex="0"></div></div><details><summary>Surrounding context</summary><div id="context" class="context"></div></details><h3>Proposed pairs</h3><p class="muted">These suggestions are assisted review aids. They are not independent gold labels.</p><div id="proposals"></div><details><summary>Details: methods, source structures, identifiers, and offsets</summary><label><input type="checkbox" id="reveal-methods"> Reveal method identities</label><div id="details" class="details-content"></div></details></main>
<aside class="panel"><h2>Your review</h2><div id="banner" class="banner hidden" role="status"></div><div class="missed"><strong>Did the suggestions miss a definition in this passage?</strong><div><label><input type="radio" name="missed" value="none"> No missed definition</label></div><div><label><input type="radio" name="missed" value="missed"> Yes, I found one</label></div><div><label><input type="radio" name="missed" value="unsure"> Unsure</label></div></div><div class="editor"><h3>Correct or add a pair</h3><p class="muted">Select text in the passage, then assign it as the short or long form.</p><div id="selection" class="selection">No text selected.</div><div class="choice-row"><button id="use-sf" class="ghost">Use as short form</button><button id="use-lf" class="ghost">Use as long form</button></div><label class="field">Short form<input id="sf-text" readonly></label><label class="field">Long form<input id="lf-text" readonly></label><div class="choice-row"><button id="apply-correction">Apply correction</button><button id="add-pair">Add missed definition</button><button id="clear-editor" class="secondary">Clear</button></div></div><label class="field">Notes<textarea id="notes" rows="5"></textarea></label><div class="actions"><button id="save">Save</button><button id="save-next">Save and next</button><a class="button secondary" href="/api/export/json">JSON backup</a><a class="button secondary" href="/api/export/bioc">BioC XML</a></div><div class="actions" style="margin-top:8px"><label class="button secondary file-label">Import JSON<input id="import-json" class="hidden" type="file" accept="application/json"></label><label class="button secondary file-label">Import BioC<input id="import-bioc" class="hidden" type="file" accept=".xml,application/xml,text/xml"></label></div></aside>
</div>
<script>
'use strict';
const byId=id=>document.getElementById(id);let packet,state,index=0,filter='all',draft,selectedSpan=null,editingSuggestion=null,dirty=false,saving=false;
const cpSlice=(text,start,end)=>Array.from(text).slice(start,end).join('');
function element(tag,text,className){const node=document.createElement(tag);if(text!==undefined)node.textContent=text;if(className)node.className=className;return node}
function empty(node){while(node.firstChild)node.removeChild(node.firstChild)}
function showBanner(message,kind='ok'){const node=byId('banner');node.textContent=message;node.className='banner '+kind}
function caseAnnotation(c){return state.annotations[c.case_id]||null}
function baseSnapshot(c){return {pairs:c.suggestions.map(s=>({decision_id:'decision-'+s.suggestion_id,suggestion_id:s.suggestion_id,proposal_kind:s.proposal_kind,status:'unreviewed',short_form:s.short_form,long_form:s.long_form,origin:'assisted',notes:''})),missed_definition:'unreviewed',notes:''}}
function loadDraft(c){const saved=caseAnnotation(c),base=baseSnapshot(c);if(!saved){draft=structuredClone(base)}else{const savedPairs=saved.current.pairs,bySuggestion=new Map(savedPairs.filter(p=>p.suggestion_id).map(p=>[p.suggestion_id,p]));draft=structuredClone({...base,...saved.current,pairs:[...base.pairs.map(p=>bySuggestion.get(p.suggestion_id)||p),...savedPairs.filter(p=>!p.suggestion_id)]})}dirty=false;selectedSpan=null;editingSuggestion=null}
function visibleCases(){return packet.cases.map((c,n)=>({c,n})).filter(x=>filter==='all'||x.c.category===filter)}
function reviewed(c){const a=caseAnnotation(c);if(!a)return false;return a.current.missed_definition!=='unreviewed'&&a.current.pairs.every(p=>p.status!=='unreviewed')}
function renderCounts(){const done=packet.cases.filter(reviewed).length;byId('counts').textContent=done+' reviewed · '+(packet.cases.length-done)+' remaining'}
function renderFilters(){const host=byId('filters');empty(host);['all',...new Set(packet.cases.map(c=>c.category))].forEach(value=>{const b=element('button',value==='all'?'All':value.replaceAll('_',' '),'ghost'+(filter===value?' active':''));b.addEventListener('click',async()=>{if(!(await saveIfDirty()))return;filter=value;renderFilters();renderList();const visible=visibleCases();if(visible.length&&!visible.some(x=>x.n===index))show(visible[0].n)});host.appendChild(b)})}
function renderList(){const host=byId('case-list');empty(host);visibleCases().forEach(({c,n})=>{const b=element('button',(n+1)+'. '+c.title,'case'+(n===index?' active':'')+(reviewed(c)?' reviewed':''));b.addEventListener('click',async()=>{if(n===index||await saveIfDirty())show(n)});host.appendChild(b)})}
function roleSegments(c){const spans=[];c.suggestions.forEach(s=>{if(s.short_form)spans.push({...s.short_form,role:'sf'});if(s.long_form)spans.push({...s.long_form,role:'lf'})});draft.pairs.forEach(p=>{if(p.short_form)spans.push({...p.short_form,role:'sf'});if(p.long_form)spans.push({...p.long_form,role:'lf'})});const bounds=[0,Array.from(c.text).length,...spans.flatMap(s=>[s.start,s.end])].sort((a,b)=>a-b);return [...new Set(bounds)].slice(0,-1).map((start,j)=>{const end=[...new Set(bounds)][j+1];const roles=new Set(spans.filter(s=>s.start<end&&s.end>start).map(s=>s.role));return {start,end,roles}})}
function renderPassage(c){const host=byId('passage');empty(host);roleSegments(c).forEach(seg=>{const text=cpSlice(c.text,seg.start,seg.end);if(!seg.roles.size){host.appendChild(document.createTextNode(text));return}const mark=element('mark',text,seg.roles.size===2?'both':[...seg.roles][0]);mark.setAttribute('aria-label',(seg.roles.has('sf')?'Short form':'')+(seg.roles.size===2?' and ':'')+(seg.roles.has('lf')?'Long form':''));host.appendChild(mark)})}
function choice(name,label,value,current,onchange){const wrapper=element('label');const radio=document.createElement('input');radio.type='radio';radio.name=name;radio.value=value;radio.checked=current===value;radio.addEventListener('change',onchange);wrapper.append(radio,document.createTextNode(' '+label));return wrapper}
function renderProposals(c){const host=byId('proposals');empty(host);draft.pairs.forEach((p,n)=>{const box=element('div',undefined,'proposal');const sf=p.short_form?p.short_form.text:'—';const lf=p.long_form?p.long_form.text:'—';box.appendChild(element('h4',p.proposal_kind==='span'?'Independent span proposal':lf+' → '+sf));const row=element('div',undefined,'choice-row');[['correct','Correct'],['incorrect','Incorrect'],['unsure','Unsure']].forEach(([value,label])=>row.appendChild(choice('pair-'+n,label,value,p.status,()=>{p.status=value;dirty=true;renderPassage(c)})));box.appendChild(row);if(p.suggestion_id){const edit=element('button','Correct spans','ghost');edit.addEventListener('click',()=>startCorrection(p));box.appendChild(edit)}else{const remove=element('button','Remove added pair','ghost');remove.addEventListener('click',()=>{draft.pairs.splice(n,1);dirty=true;renderAll()});box.appendChild(remove)}host.appendChild(box)});if(!draft.pairs.length)host.appendChild(element('p','No pair or span was proposed for this passage.','muted'))}
function renderDetails(c){const revealed=byId('reveal-methods').checked;const methods=revealed?c.suggestions.map(s=>({suggestion_id:s.suggestion_id,method_ids:s.method_ids,provenance:s.provenance})):c.suggestions.map(s=>({suggestion_id:s.suggestion_id,method_ids:'hidden',provenance:'hidden'}));const diagnostics=revealed?c.method_diagnostics:c.method_diagnostics.map(d=>({status:d.status,coverage:d.coverage,diagnostics:d.diagnostics}));byId('details').textContent=JSON.stringify({case_id:c.case_id,inventory_id:c.inventory_id,section_id:c.section_id,passage_offsets:[c.passage_start,c.passage_end],suggestions:methods,method_diagnostics:diagnostics,structures:c.structures,source_comparisons:c.source_comparisons},null,2)}
function sourceLabel(c){return c.arm==='pmc_cc_by'?'Full-text article · '+c.section_heading:'PubMed abstract · '+c.section_heading}
function renderAll(){const c=packet.cases[index];byId('article-title').textContent=c.title;const source=byId('source-line');empty(source);source.append(document.createTextNode(sourceLabel(c)+' · '));const a=element('a','Open source');a.href=c.source_url;a.target='_blank';a.rel='noreferrer';source.appendChild(a);byId('context').textContent=[c.context_before,c.context_after].filter(Boolean).join('\n\n[Passage to review]\n\n');byId('position').textContent=(index+1)+' of '+packet.cases.length;renderPassage(c);renderProposals(c);renderDetails(c);byId('notes').value=draft.notes;document.querySelectorAll('input[name=missed]').forEach(r=>r.checked=r.value===draft.missed_definition);renderEditor();renderCounts();renderList()}
function show(n){index=n;loadDraft(packet.cases[index]);showBanner('Loaded case. Changes are saved to disk only when you use Save.');renderAll();history.replaceState(null,'','#case='+encodeURIComponent(packet.cases[index].case_id))}
function selectionOffsets(){const selection=window.getSelection(),host=byId('passage');if(!selection||selection.rangeCount!==1||selection.isCollapsed)return null;const range=selection.getRangeAt(0);if(!host.contains(range.commonAncestorContainer))return null;const prefix=range.cloneRange();prefix.selectNodeContents(host);prefix.setEnd(range.startContainer,range.startOffset);const start=Array.from(prefix.toString()).length,text=range.toString(),end=start+Array.from(text).length;if(!text||cpSlice(packet.cases[index].text,start,end)!==text)return null;return {start,end,text}}
function captureSelection(){selectedSpan=selectionOffsets();byId('selection').textContent=selectedSpan?'Selected: “'+selectedSpan.text+'”':'No text selected.'}
function startCorrection(pair){editingSuggestion=pair.suggestion_id;draft.editor={short_form:pair.short_form,long_form:pair.long_form};renderEditor();byId('sf-text').focus()}
function renderEditor(){const e=draft.editor||{};byId('sf-text').value=e.short_form?e.short_form.text:'';byId('lf-text').value=e.long_form?e.long_form.text:''}
function assign(role){if(!selectedSpan){showBanner('Select exact text in the passage first.','error');return}draft.editor=draft.editor||{};draft.editor[role]=selectedSpan;renderEditor()}
function clearEditor(){delete draft.editor;editingSuggestion=null;selectedSpan=null;byId('selection').textContent='No text selected.';renderEditor()}
function applyCorrection(){if(!editingSuggestion){showBanner('Choose Correct spans on a proposed pair first.','error');return}const pair=draft.pairs.find(p=>p.suggestion_id===editingSuggestion);if(!pair)return;const e=draft.editor||{};if(!e.short_form&&!e.long_form){showBanner('Assign at least one selected span.','error');return}pair.short_form=e.short_form||null;pair.long_form=e.long_form||null;pair.origin='corrected';pair.status='unsure';dirty=true;clearEditor();renderAll();showBanner('Correction staged. Save to write it to disk.')}
function addPair(){const e=draft.editor||{};if(!e.short_form||!e.long_form){showBanner('A missed definition needs both a short form and long form.','error');return}draft.pairs.push({decision_id:'added-'+crypto.randomUUID(),suggestion_id:null,proposal_kind:'definition',status:'correct',short_form:e.short_form,long_form:e.long_form,origin:'added',notes:''});draft.missed_definition='missed';dirty=true;clearEditor();renderAll();showBanner('Missed definition staged. Save to write it to disk.')}
async function responseJson(response){let body;try{body=await response.json()}catch{throw Error('The reviewer returned an unreadable response.')}if(!response.ok)throw Error(body.error||'Request failed ('+response.status+').');return body}
async function save(goNext=false){if(saving)return false;saving=true;document.querySelectorAll('button').forEach(b=>b.disabled=true);try{draft.notes=byId('notes').value;delete draft.editor;const c=packet.cases[index],existing=caseAnnotation(c);const body={schema_version:'t052-annotation-submission-v2',packet_id:packet.packet_id,packet_content_sha256:packet.content_sha256,current_case_id:c.case_id,annotations:{[c.case_id]:{expected_revision:existing?existing.revision:0,decision:draft}}};state=await responseJson(await fetch('/api/annotations',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}));dirty=false;showBanner('Saved revision '+state.annotations[c.case_id].revision+' to disk.');renderCounts();renderList();if(goNext)await navigate(1);return true}catch(error){showBanner('Save failed: '+error.message+'. You are still on this case; your edits remain on screen.','error');return false}finally{saving=false;document.querySelectorAll('button').forEach(b=>b.disabled=false)}}
async function saveIfDirty(){return dirty?save(false):true}
async function navigate(delta){if(!(await saveIfDirty()))return;const visible=visibleCases(),at=visible.findIndex(x=>x.n===index),next=visible[(at+delta+visible.length)%visible.length];if(next!==undefined)show(next.n)}
async function importFile(file,kind){if(!file)return;try{const body=await file.arrayBuffer(),type=kind==='json'?'application/json':'application/xml';state=await responseJson(await fetch('/api/import/'+kind,{method:'POST',headers:{'Content-Type':type},body}));const resume=state.current_case_id,found=packet.cases.findIndex(c=>c.case_id===resume);show(found>=0?found:index);showBanner((kind==='json'?'JSON':'BioC')+' import validated and saved.')}catch(error){showBanner('Import failed: '+error.message,'error')}}
async function init(){try{packet=await responseJson(await fetch('/api/packet'));state=await responseJson(await fetch('/api/annotations'));byId('meta').textContent=packet.cases.length+' cases · '+packet.packet_id+' · content '+packet.content_sha256.slice(0,12);renderFilters();const hash=new URLSearchParams(location.hash.slice(1)).get('case'),wanted=hash||state.current_case_id,found=packet.cases.findIndex(c=>c.case_id===wanted);show(found>=0?found:0)}catch(error){showBanner('Reviewer could not load: '+error.message,'error');byId('meta').textContent='Load failed'}}
byId('passage').addEventListener('mouseup',captureSelection);byId('passage').addEventListener('keyup',captureSelection);byId('use-sf').addEventListener('click',()=>assign('short_form'));byId('use-lf').addEventListener('click',()=>assign('long_form'));byId('apply-correction').addEventListener('click',applyCorrection);byId('add-pair').addEventListener('click',addPair);byId('clear-editor').addEventListener('click',clearEditor);byId('notes').addEventListener('input',()=>dirty=true);document.querySelectorAll('input[name=missed]').forEach(r=>r.addEventListener('change',()=>{draft.missed_definition=r.value;dirty=true}));byId('reveal-methods').addEventListener('change',()=>renderDetails(packet.cases[index]));byId('save').addEventListener('click',()=>save(false));byId('save-next').addEventListener('click',()=>save(true));byId('previous').addEventListener('click',()=>navigate(-1));byId('next').addEventListener('click',()=>navigate(1));byId('import-json').addEventListener('change',event=>importFile(event.target.files[0],'json'));byId('import-bioc').addEventListener('change',event=>importFile(event.target.files[0],'bioc'));window.addEventListener('beforeunload',event=>{if(dirty){event.preventDefault();event.returnValue=''}});init();
</script><script>
document.querySelector('.editor').addEventListener('click',event=>{if(event.target.id==='apply-correction'||event.target.id==='add-pair'||event.target.id==='clear-editor')document.querySelector('.editor').classList.add('open')});
</script></body></html>"""
